using System.Xml.Linq;
using VisionEditor.Core;
int count=0;void Check(bool condition,string label){if(!condition)throw new Exception(label);count++;}
var path=Path.Combine(AppContext.BaseDirectory,"ImageSourceModuleAlgorithmTab.xml");var definition=VmPluginUiDefinition.Load(path);
Check(definition.ChineseWidth==420&&definition.ChineseHeight==500,"original declared content size");Check(definition.Tabs.Count==1&&definition.Tabs[0].Name=="Tab_Basic Params","only declared original tab");Check(definition.Tabs[0].Categories.Count==3,"three original categories");var items=definition.Tabs.SelectMany(t=>t.Categories).SelectMany(c=>c.Items).ToArray();Check(items.Length==25,"all 25 original controls retained");var source=items.Single(i=>i.Name=="ImageSourceType");var xml=XElement.Parse(source.OriginalXml);Check(xml.Element("EnumEntrys")!.Elements().Count()==3,"local camera sdk enum modes");Check(xml.Element("Triggers") is not null,"visibility triggers retained");Check(items.Single(i=>i.Name=="CurrentImagePath").Kind=="ButtonSelecter_ImageList","custom file list selector preserved");Check(definition.ExternItems.Any(i=>i.Kind=="LocalImageList"),"external custom image list preserved");Check(definition.BottomButtons.Count==0,"no invented confirm or apply buttons");Check(XElement.Parse(definition.OriginalXml).Name.LocalName=="AlgorithmTabRoot","unknown XML retained losslessly as declaration");Console.WriteLine($"{count} original plugin declaration checks passed.");
